-- =============================================================================
-- University of Nigeria, Nsukka — Faculty of Biological Sciences
-- Plant Science and Biotechnology
-- Course outlines transcribed from the departmental course catalogue.
-- =============================================================================
-- Run in the Supabase SQL Editor. Safe to run more than once: existing rows
-- for these courses are removed first, so it updates rather than duplicates.
--
-- This file also carries the required ancillary and general-studies courses
-- a Plant Science and Biotechnology student actually sits each semester
-- (BIO, CHM, MTH, PHY, GSP, COS, CED, SSC, STA, plus BCH 201/202, ZEB
-- 201/202/301 and MCB 201/102), scoped to department = 'Plant Science and
-- Biotechnology' so they appear on this department's own timetable —
-- independent rows from any same-code row filed under its own home
-- department. Descriptions are reused, unedited, from this app's
-- Biochemistry/Microbiology/Zoology/Mathematics/Physics/Chemistry outlines
-- where the code, level, semester and subject genuinely match; where no
-- verified description exists anywhere (BIO, GSP, COS, CED, SSC, STA, CHM
-- 232), only code/title/units/level/semester are given. Ancillary lists
-- follow only the catalogue's own Standard Four-Year Programme table, not
-- its Three-Year direct-entry or combined-honours variants.
-- =============================================================================

delete from public.course_outlines
 where institution = 'University of Nigeria, Nsukka'
   and department = 'Plant Science and Biotechnology';

insert into public.course_outlines
  (course_code, course_title, institution, faculty, department, level,
   semester, credit_units, description, topics, contributor_name)
values
  ('PSB 101', 'General Plant Science', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '100 Level', 'first', 2, 'Survey of plant groups from algae/fungi to angiosperms. Comparative morphology of all major groups of plants with special emphasis on the local flora. General anatomy of monocotyledonous and dicotyledonous flora. General principles of plant morphology. The principles and processes involved and uses of various structures (whole plants, plant parts and products) discussed to highlight their utilisation for provision of goods and services.', '["Survey of plant groups from algae/fungi to angiosperms", "Comparative morphology of major plant groups, with emphasis on local flora", "General anatomy of monocotyledonous and dicotyledonous flora", "General principles of plant morphology", "Uses of whole plants, plant parts and products for goods and services"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 102', 'General Plant Biotechnology', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '100 Level', 'second', 2, 'Definition, origin and history of plant biotechnology. Basic terminologies used in biotechnology. Introduction to basic in vitro techniques. Concept of cell totipotency. Explants for in vitro culture (embryo, seed, meristem, organs, etc). Tissue culture media: preparation and storage. Sterilisation techniques (labwares/media/explants). Cultural conditions (chemical and physical environments). Isolation of nucleic acids and proteins. Introduction to genes and genomes. Applications of biotechnology in industries, agriculture, health, environment, forensics, biological warfare, etc.', '["Definition, origin and history of plant biotechnology", "Basic terminologies used in biotechnology", "Introduction to basic in vitro techniques and cell totipotency", "Explants for in vitro culture: embryo, seed, meristem, organs", "Tissue culture media: preparation and storage", "Sterilisation techniques for labware, media and explants", "Cultural conditions: chemical and physical environments", "Isolation of nucleic acids and proteins; introduction to genes and genomes", "Applications of biotechnology in industry, agriculture, health, environment, forensics, biological warfare"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 162', 'Climate Change and Plant Life I', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '100 Level', 'second', 1, 'Concept of weather and climate, climatic factors. Past climates, glacial etc and vegetation types (fossil plants). Present climatic zones of the earth and vegetation types: tropical rain forest, savanna, mangrove, etc. Reconstruction of past climates through fossil studies: phytoplankton, algae, pollen, etc.', '["Concept of weather and climate; climatic factors", "Past climates, glacial periods and vegetation types (fossil plants)", "Present climatic zones of the earth and vegetation types: rain forest, savanna, mangrove", "Reconstruction of past climates through fossil studies: phytoplankton, algae, pollen"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 211', 'Phycology and Bryology', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '200 Level', 'first', 2, 'Structure, reproduction, adaptation, life cycle and economic importance, etc, of the algae and bryophytes, as well as industrial uses of these lower plants.', '["Structure, reproduction, adaptation and life cycle of algae and bryophytes", "Economic importance and industrial uses of lower plants"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 213', 'Morphology and Phytosystematics of Pteridophytes and Gymnosperms', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '200 Level', 'first', 2, 'General features and classification of Pteridophytes and Gymnosperms (both living and extinct). Alternation of generations. Types, organisational structure and development of sporangia. Types of steles. Life history of selected members of various families.', '["General features and classification of Pteridophytes and Gymnosperms (living and extinct)", "Alternation of generations", "Types, organisational structure and development of sporangia", "Types of steles", "Life history of selected members of various families"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 221', 'General Plant Anatomy', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '200 Level', 'first', 2, 'The origin of the primary body of plants. The structures, organisation and functions of plant cells, tissues and tissue systems. Plant cells for storage of food and other ergastic substances. Anatomy of monocotyledonous and dicotyledonous stem, roots and leaves. Anatomy of xerophytes and hydrophytes. The cambium and its derivatives. Xylem and bark in relation to activity. Anomalous secondary growth. Reaction wood. Gymnosperm wood. Plant micro-techniques.', '["Origin of the primary body of plants", "Structures, organisation and functions of plant cells, tissues and tissue systems", "Plant cells for storage of food and other ergastic substances", "Anatomy of monocotyledonous and dicotyledonous stem, roots and leaves", "Anatomy of xerophytes and hydrophytes", "The cambium and its derivatives; xylem and bark in relation to activity", "Anomalous secondary growth; reaction wood; gymnosperm wood", "Plant micro-techniques"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 241', 'General Mycology', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '200 Level', 'first', 2, 'A general account of the concepts of origin, affinities, distribution and economic importance of fungi. Morphology, taxonomy and reproduction of various classes of fungi with emphasis on local flora. An introduction to the construction of dichotomous keys through understanding of mycological terminologies. Collection and preparation of herbarium specimens.', '["Origin, affinities, distribution and economic importance of fungi", "Morphology, taxonomy and reproduction of various classes of fungi, with emphasis on local flora", "Construction of dichotomous keys through mycological terminologies", "Collection and preparation of herbarium specimens"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 261', 'Climate Change and Plant Life II', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '200 Level', 'first', 1, 'Causes of climate change, natural and anthropogenic; pollution — air, water and land (causes, impact and mitigation); global warming — definition, greenhouse gases (sources, impact and mitigation). Impacts of climate change on life and environment, climate change and natural disasters; soil erosion; flooding; fire; environmental degradation, desert encroachment, etc. Effects of climate change on causation of pattern of plant distribution and reproduction and vegetation, etc.', '["Causes of climate change: natural and anthropogenic", "Air, water and land pollution: causes, impact and mitigation", "Global warming: definitions, greenhouse gases, impact and mitigation", "Impacts of climate change on life and environment: natural disasters, soil erosion, flooding, fire, desert encroachment", "Effects of climate change on plant distribution, reproduction and vegetation"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 246', 'General Plant Pathology', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '200 Level', 'second', 2, 'Morphology and taxonomy of plant pathogens. Collection, isolation and identification of pathogenic plants, etc.', '["Morphology and taxonomy of plant pathogens", "Collection, isolation and identification of pathogenic plants"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 272', 'Mushroom Technology', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '200 Level', 'second', 2, 'History of mushroom cultivation. Collection, identification and preservation of mushrooms. Spawn production. Inoculation procedures and cultivation of mushrooms. Pests and diseases of mushrooms. Industrial production and marketing of mushrooms, etc.', '["History of mushroom cultivation", "Collection, identification and preservation of mushrooms", "Spawn production; inoculation procedures and cultivation of mushrooms", "Pests and diseases of mushrooms", "Industrial production and marketing of mushrooms"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 274', 'Plant Macropropagation and Floriculture', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '200 Level', 'second', 1, 'Evaluation of the economic values of indigenous and exotic horticultural plants. Different propagation techniques for rapid propagation of indigenous tree crops. Growing flowers from seeds and cuttings, nursery techniques, hydroponics and use of plant hormones for accelerated propagation. Irrigation and dry season production of fruits and vegetables. Phenology and conservation.', '["Economic values of indigenous and exotic horticultural plants", "Propagation techniques for rapid propagation of indigenous tree crops", "Growing flowers from seeds and cuttings; nursery techniques; hydroponics; plant hormones for accelerated propagation", "Irrigation and dry season production of fruits and vegetables", "Phenology and conservation"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 301', 'Phytotechniques', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '300 Level', 'first', 2, 'Biological drawings, microtomy, microscopy, autoclaving, photography and photomicroscopy, preparation of microscope slides, cytological techniques, collection and preservation of plant specimens; introductory herbarium techniques, mycological techniques, photometry, colourimetry, chromatography, chlorometry, amino acid analysis, etc.', '["Biological drawings, microtomy, microscopy and autoclaving", "Photography and photomicroscopy; preparation of microscope slides", "Cytological techniques; collection and preservation of plant specimens", "Introductory herbarium and mycological techniques", "Photometry, colourimetry, chromatography, chlorometry and amino acid analysis"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 303', 'Ethnomedicinal Plants', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '300 Level', 'first', 2, 'Description, identification and classification of medicinal plants. Preparation of extracts from various organs of plants. Gathering of ethnomedical information. Collection and conservation of medicinal plants. Relation of the medicinal qualities of plants to their habits, structures, functions and ecological niches. Refining of ethnomedicinal practices by indigenous people in relation to correct dosage and elimination of contaminants.', '["Description, identification and classification of medicinal plants", "Preparation of extracts from various organs of plants", "Gathering of ethnomedical information", "Collection and conservation of medicinal plants", "Relation of medicinal qualities to plant habits, structures, functions and ecological niches", "Refining ethnomedicinal practices: correct dosage and elimination of contaminants"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 313', 'Morphology and Phytosystematics of Higher Plants', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '300 Level', 'first', 2, 'General morphology of Angiosperms: root, stem, leaf and shoot modifications. Ontogeny and morphological interpretation of flowers. Structure and development of anther and ovule. Types of inflorescences. Features of selected families. Classical and modern taxonomy. Origin of monocotyledons. Collection, identification and preservation of plant materials.', '["General morphology of Angiosperms: root, stem, leaf and shoot modifications", "Ontogeny and morphological interpretation of flowers", "Structure and development of anther and ovule", "Types of inflorescences; features of selected families", "Classical and modern taxonomy; origin of monocotyledons", "Collection, identification and preservation of plant materials"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 315', 'Palaeobotany', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '300 Level', 'first', 2, 'Floral biology; micropalaeobotany of spores and pollens. Carbon dating. Evolution and systematics of plants. Principles and uses of palaeoecology. Fossilisation — types and prevailing conditions. Reconstruction of past flora, communities and environment using fossil deposits, etc.', '["Floral biology; micropalaeobotany of spores and pollens", "Carbon dating", "Evolution and systematics of plants", "Principles and uses of palaeoecology", "Fossilisation: types and prevailing conditions", "Reconstruction of past flora, communities and environment using fossil deposits"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 331', 'General Plant Physiology', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '300 Level', 'first', 2, 'The physical and chemical properties of living plant cells; water, mineral and soil relations of plants; intermediary metabolism, growth and development. Respiration, photosynthesis. Protein synthesis. Absorption and translocation. The control of growth and differentiation, plant growth hormones. The control of development, hormones and gene activity. Plant manometry, chromatography and bioassay of growth hormone. Practical work covering the above topics.', '["Physical and chemical properties of living plant cells", "Water, mineral and soil relations of plants", "Intermediary metabolism, growth and development", "Respiration, photosynthesis and protein synthesis", "Absorption and translocation", "Control of growth and differentiation; plant growth hormones", "Control of development, hormones and gene activity", "Plant manometry, chromatography and bioassay of growth hormone"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 355', 'General Plant Molecular Biology', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '300 Level', 'first', 2, 'Biogenesis of microtubules, microfilaments, golgi and mitochondria. Membrane-membrane interactions. Introduction to bioenergetics and thermodynamics. History and present trends in molecular biology. Reproduction, cell division, cell differentiation and growth of cells: a brief study of the molecular basis of cell structure and development. Organelles — chloroplasts, cellulose cell wall. Plant proteins and nucleic acids. Electrophoresis and its principles; agarose gel electrophoresis, SDS-PAGE, etc.', '["Biogenesis of microtubules, microfilaments, golgi and mitochondria", "Membrane-membrane interactions", "Introduction to bioenergetics and thermodynamics", "History and present trends in molecular biology", "Molecular basis of cell structure and development; reproduction, cell division and differentiation", "Organelles: chloroplasts, cellulose cell wall", "Plant proteins and nucleic acids", "Electrophoresis principles: agarose gel electrophoresis, SDS-PAGE"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 363', 'Forest Resources Conservation', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '300 Level', 'first', 2, 'Major features of Nigerian vegetation types. Forest resources with emphasis on timber, food, medicine and industrial raw materials. Effects of deforestation and afforestation. Methods for sustainable conservation of forest resources.', '["Major features of Nigerian vegetation types", "Forest resources: timber, food, medicine and industrial raw materials", "Effects of deforestation and afforestation", "Methods for sustainable conservation of forest resources"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 365', 'Vulnerability and Adaptation of Plants to Climate Change', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '300 Level', 'first', 1, 'Adaptive features and physiognomy of trees and shrubs. Physiological adaptations to climate change. C3 and C4 plants. Influence of climate change on periodicity of plants, seed dormancy, dispersal, germination and vegetative propagation. Environmental impact assessment and climate change. Climate change and plant evolution. Plant breeding relative to climate change. Field studies on impact of climate change on plants in diverse ecological habitats, etc.', '["Adaptive features and physiognomy of trees and shrubs", "Physiological adaptations to climate change; C3 and C4 plants", "Influence of climate change on plant periodicity, seed dormancy, dispersal, germination and vegetative propagation", "Environmental impact assessment and climate change", "Climate change and plant evolution", "Plant breeding relative to climate change", "Field studies on impact of climate change on plants in diverse ecological habitats"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 367', 'Climate Change and Global Mitigation Strategies', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '300 Level', 'first', 1, 'Reduction of carbon emissions, recycling, tree seedling production. Carbon sequestration strategies. Tree planting. Global policy and mitigation issues: energy, natural resource, population, education, integrated adaptation, etc. Global policy frameworks: United Nations Framework on Climate Change (UNFCCC), Kyoto Protocol, UN Conference on Environment and Development — Rio de Janeiro, Johannesburg Summit, Copenhagen Climate Change Summit, etc.', '["Reduction of carbon emissions, recycling, tree seedling production", "Carbon sequestration strategies and tree planting", "Global policy and mitigation issues: energy, natural resources, population, education, integrated adaptation", "Global policy frameworks: UNFCCC, Kyoto Protocol, Rio Conference, Johannesburg Summit, Copenhagen Climate Change Summit"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 371', 'Principles of Plant Biotechnology', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '300 Level', 'first', 2, 'Traditional biotechnology, microbial fermentation, etc. DNA: types and functions; basic structure of DNA; DNA replication, transcription and translation; concept of genes; genetic codes and gene expression; genetic modifications in living organisms; types of DNA in living organisms and their locations in the cell; gene cloning; introduction of foreign gene into a host, transformation and transfection; restriction enzymes and other enzymes used in genetic engineering; cloning vectors — plasmids, bacteriophages, Yeast Artificial Chromosomes (YACs), Bacterial Artificial Chromosomes (BACs), Agrobacterium tumefaciens in gene transfer, gene gun, etc. Genetic engineering of plants and creation of transgenic plants.', '["Traditional biotechnology and microbial fermentation", "DNA types and functions; basic structure, replication, transcription and translation", "Concept of genes; genetic codes and gene expression; genetic modifications in living organisms", "Gene cloning; transformation and transfection", "Restriction enzymes and other enzymes used in genetic engineering", "Cloning vectors: plasmids, bacteriophages, YACs, BACs, Agrobacterium tumefaciens, gene gun", "Genetic engineering of plants and creation of transgenic plants"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 391', 'Research Methods and Plant Breeding', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '300 Level', 'first', 2, 'Field and laboratory data collection, categorisation, organisation and presentation. Experimental designs and data analysis. Introductory principles and practice of plant breeding. Course is designed to prepare students for sound experimental designs, data interpretations and development of independent research capabilities in their final year.', '["Field and laboratory data collection, categorisation, organisation and presentation", "Experimental designs and data analysis", "Introductory principles and practice of plant breeding", "Preparation for sound experimental design, data interpretation and independent research"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 392', 'Students Industrial Work Experience (SIWES) Field Work', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '300 Level', 'second', 6, 'Industrial attachment in an approved Plant Science and Biotechnology based industry/organisation for 6 months.', '["Industrial attachment in an approved Plant Science and Biotechnology based industry/organisation for 6 months"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 394', 'SIWES Report', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '300 Level', 'second', 6, 'Detailed written report on activities carried out during the industrial work experience.', '["Detailed written report on activities carried out during the industrial work experience"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 396', 'SIWES Seminar', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '300 Level', 'second', 3, 'Oral and visual presentation based on the industrial work experience, using accumulated data and experience, from the 6 months exercise.', '["Oral and visual presentation based on the industrial work experience", "Presentation of accumulated data and experience from the 6-month exercise"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 411', 'Dendrology', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 2, 'Morphology of plants and organs. Marking vegetation; physiognomy of trees and shrubs of the Nigerian rain forest and savannas — stilt roots, pneumatophores, bole and crown shape of Nigerian flora. Forest ecology. Beyond the forest. Elementary forest mensuration. Silviculture.', '["Morphology of plants and organs", "Physiognomy of trees and shrubs of the Nigerian rain forest and savannas: stilt roots, pneumatophores, bole and crown shape", "Forest ecology", "Elementary forest mensuration", "Silviculture"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 413', 'Herbarium and Phytosystematics', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 2, 'The studies of taxonomic characters; taxonomic evidence from external morphology, anatomy, cytology, phytochemistry. Variation within population. Population and environment. Computers and taxonomy. Uses of phytosystematics in special areas like pharmacognosy, palynology, phytogeography, etc. Chemical plant taxonomy, past and recent advances in taxonomic research.', '["Studies of taxonomic characters; taxonomic evidence from morphology, anatomy, cytology and phytochemistry", "Variation within population; population and environment", "Computers and taxonomy", "Uses of phytosystematics in pharmacognosy, palynology and phytogeography", "Chemical plant taxonomy; recent advances in taxonomic research"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 415', 'Introductory Palynology', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 2, 'Outline and history of palynology; aspects of palynology. The pollen grain: its form and function; morphological terminology, pollen and spores; development, physiology and biochemistry; principles of pollination ecology, the production and dispersal of pollen and spores; pollen analysis in palaeoecology, geology, melissopalynology, oil and petrochemical industries, etc.', '["Outline and history of palynology", "The pollen grain: form, function and morphological terminology", "Development, physiology and biochemistry of pollen and spores", "Principles of pollination ecology; production and dispersal of pollen and spores", "Pollen analysis in palaeoecology, geology, melissopalynology, oil and petrochemical industries"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 417', 'Freshwater Phycology', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 2, 'Identification of freshwater algae. Types of freshwater habitats and their characteristics. Algal habitats and their characteristics. Sampling techniques, population estimates and dynamics in relation to seasonal changes. Aquatic pollution. Economic importance of algae, etc.', '["Identification of freshwater algae", "Types of freshwater habitats and algal habitats and their characteristics", "Sampling techniques, population estimates and dynamics in relation to seasonal changes", "Aquatic pollution", "Economic importance of algae"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 431', 'Advances in Plant Physiology', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 2, 'Respiration. Photosynthesis. Protein synthesis. Absorption and translocation. The control of growth and differentiation, plant growth hormones. The control of development, hormones and gene activity. Plant manometry, chromatography and bioassay of growth hormone, etc.', '["Respiration, photosynthesis and protein synthesis", "Absorption and translocation", "Control of growth and differentiation; plant growth hormones", "Control of development, hormones and gene activity", "Plant manometry, chromatography and bioassay of growth hormone"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 433', 'Plant Embryology and Morphogenesis', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 2, 'Embryo development including endosperm formation. Polyembryony; apomixis. The seed. Embryology in relation to taxonomy. Experimental and applied embryology. Plant apical organisation. Tissue differentiation, differentiation without growth. Development pattern. Symmetry and form. Regeneration in lower and higher plants. Chimeras. Abnormal development of organs. Morphogenetic factors and growth. Use of seedling, organ, tissue and cell culture techniques.', '["Embryo development including endosperm formation", "Polyembryony and apomixis; the seed", "Embryology in relation to taxonomy; experimental and applied embryology", "Plant apical organisation; tissue differentiation, differentiation without growth", "Development pattern; symmetry and form", "Regeneration in lower and higher plants; chimeras", "Abnormal development of organs; morphogenetic factors and growth", "Use of seedling, organ, tissue and cell culture techniques"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 441', 'Advances in Plant Pathology', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 2, 'Survey of classification of plant pathogens and diseases. Principles of plant infection, disease transmission and epidemiology. Physiology and anatomy of the diseased plant. Relation of environment to disease development. Principles of plant disease control. Review study of selected plant diseases.', '["Classification of plant pathogens and diseases", "Principles of plant infection, disease transmission and epidemiology", "Physiology and anatomy of the diseased plant", "Relation of environment to disease development", "Principles of plant disease control", "Review study of selected plant diseases"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 443', 'Fungus Physiology', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 2, 'Composition of fungal cells, liberation and germination of spores. Growth and reproduction. Nutrition and metabolism. Synthesis of lipids and proteins. Vitamin requirements and their production. Microbial antagonism.', '["Composition of fungal cells; liberation and germination of spores", "Growth and reproduction", "Nutrition and metabolism; synthesis of lipids and proteins", "Vitamin requirements and their production", "Microbial antagonism"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 445', 'Plant Virology and Diagnostics', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 2, 'Survey of plant viruses with special reference to structure, physical and chemical properties; serological relationships, transmission, variability, infection, replication, movement, quantitative assays, purification and electron microscopy. Acquired immunity and environmental influence, studies of selected virus diseases and general principles of control.', '["Survey of plant viruses: structure, physical and chemical properties", "Serological relationships, transmission, variability, infection and replication", "Movement, quantitative assays, purification and electron microscopy", "Acquired immunity and environmental influence", "Studies of selected virus diseases and general principles of control"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 451', 'Cytology', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 2, 'Detailed study of the cell and its organelles at the ultrastructural level. Cytology, heredity, taxonomy and evolution. Energy balance sheet of the cell, metabolic interrelations. Variations in chromosome number and size. Karyotype analysis. Use of cytology in detection and monitoring of environmental pollutions. Effects of mutation on chromosome number and morphology. Recent advances in cytology, etc.', '["Detailed study of the cell and its organelles at the ultrastructural level", "Cytology in relation to heredity, taxonomy and evolution", "Energy balance sheet of the cell; metabolic interrelations", "Variations in chromosome number and size; karyotype analysis", "Use of cytology in detection and monitoring of environmental pollution", "Effects of mutation on chromosome number and morphology"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 453', 'Genetics and Plant Breeding', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 2, 'Studies of pure lines, Hardy-Weinberg equilibrium and quantitative inheritance, heritability, genetic drift and equilibrium, inbreeding depression and heterosis, methods of breeding including breeding for resistance. Effects of polyploidy, mutation, etc in plant breeding. Recent advances in plant breeding.', '["Pure lines, Hardy-Weinberg equilibrium and quantitative inheritance", "Heritability, genetic drift and equilibrium", "Inbreeding depression and heterosis", "Methods of breeding, including breeding for resistance", "Effects of polyploidy and mutation in plant breeding"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 455', 'Advances in Plant Molecular Biology', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 2, 'The structure, conformation and other properties of nucleic acids and proteins, with special reference to X-ray crystallography and other physical techniques. Polysaccharides, glycoproteins, cell wall structures and lignin, etc, and related biological macromolecules. Structure and properties of DNA and RNA, etc.', '["Structure, conformation and properties of nucleic acids and proteins", "X-ray crystallography and other physical techniques", "Polysaccharides, glycoproteins, cell wall structures and lignin", "Structure and properties of DNA and RNA"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 457', 'Phytobioinformatics', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 1, 'Use of computer information technology to analyse and integrate diverse biological data generated by plant biotechnological advances. Analysis of varied genomic and post-genomic data generated by the "omic" technologies. Access to GenBank meta-database for information DNA sequence data. Sharing of biotechnological information using the internet, etc.', '["Use of computer information technology to analyse and integrate biological data", "Analysis of genomic and post-genomic data from omic technologies", "Access to GenBank meta-database for DNA sequence data", "Sharing of biotechnological information using the internet"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 461', 'Aquatic and Pollution Biology', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 2, 'Types and sources of pollution. Water, land and air pollution. Methods of remediation and control of pollution. Aquatic plants: microphytes and macrophytes. Effects of pollution on plants. Plants used in phytoremediation. Economic importance of pollution, etc.', '["Types and sources of pollution: water, land and air", "Methods of remediation and control of pollution", "Aquatic plants: microphytes and macrophytes", "Effects of pollution on plants; plants used in phytoremediation"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 463', 'Economic and Industrial Botany', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 2, 'Origin and evolution of cultivated plants with special reference to Nigeria and West Africa. Productivity and the economic aspects of the utilisation of food resources, aspects of land use in crop production. Classification, botanical characteristics and economic exploitation of plants used as sources of food, fibres, oil, latex, timber, drugs, etc.', '["Origin and evolution of cultivated plants in Nigeria and West Africa", "Productivity and economic aspects of the utilisation of food resources", "Aspects of land use in crop production", "Classification, botanical characteristics and economic exploitation of plants: food, fibres, oil, latex, timber, drugs"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 467', 'Phytogeography', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 1, 'Plant distribution with emphasis on Nigerian ecosystems. Causative factors: topography, edaphic, salinity, climatic, etc. Adaptation for survival. Major ecosystems in Nigeria. Physiognomy of trees and shrubs in the tropical rain forest, savanna ecosystem.', '["Plant distribution with emphasis on Nigerian ecosystems", "Causative factors: topography, edaphic, salinity and climate", "Adaptation for survival", "Major ecosystems in Nigeria; physiognomy of trees and shrubs in rain forest and savanna"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 469', 'Plants Productivity and Apiculture', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 1, 'Apiculture, definition and history. Genetic diversity of bees. Colony life and social organisation of bees. Construction and management of apiaries. Vegetation types for bee keeping. Pollination and bee flora studies. Consultancy services to farmers for the use of apiculture in boosting crop productivity. Products and uses of apiculture. Economic importance of honey and honey products.', '["Definition and history of apiculture; genetic diversity of bees", "Colony life and social organisation of bees", "Construction and management of apiaries; vegetation types for bee keeping", "Pollination and bee flora studies", "Use of apiculture in boosting crop productivity", "Products, uses and economic importance of honey and honey products"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 471', 'Plant Tissue Culture and Micropropagation', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 2, 'Laboratory safety and principles of aseptic culture. Plant anatomy/development review. Basic media components. Types of cultures — organ, callus, cell suspension cultures, embryo rescue, protoplast isolation, culture and plant regeneration. Morphogenesis, organogenesis and embryogenesis. Applications of plant tissue culture.', '["Laboratory safety and principles of aseptic culture", "Plant anatomy/development review; basic media components", "Types of cultures: organ, callus, cell suspension, embryo rescue, protoplast isolation and regeneration", "Morphogenesis, organogenesis and embryogenesis", "Applications of plant tissue culture"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 473', 'Phyto-biofuels', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 1, 'Definitions and methods of production of bio-diesel, ethanol, methanol, smokeless coal, etc. Burning of plant organic matter for production of biofuel. Clean energy production from plant materials. Fermentation of sugar, corn, etc for biofuel production. Biofuel from algae. Ethical issues in use of food materials for biofuel production. Energy from forestry, etc.', '["Definitions and methods of production of bio-diesel, ethanol, methanol, smokeless coal", "Burning of plant organic matter for biofuel; clean energy from plant materials", "Fermentation of sugar and corn for biofuel production", "Biofuel from algae", "Ethical issues in use of food materials for biofuel production", "Energy from forestry"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 475', 'Plant Biophysics', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 2, 'Definitions and historical perspectives. Principles and techniques of physics applied to solving plant science problems, like the use of X-ray crystallography in the analysis of DNA structure, etc. Effects of magnetism, electromagnetism, light of different wavelengths, nanoparticles, ionizing radiations, various mutagenic agents, sound vibrations, radio waves, base station and handset radiations, microwave and electronic gadget radiations, high tension electric wires, etc, on plant cells, tissues, organs, responses, growth, productivity, etc.', '["Principles and techniques of physics applied to plant science problems", "Use of X-ray crystallography in the analysis of DNA structure", "Effects of magnetism, electromagnetism and light of different wavelengths on plants", "Effects of nanoparticles, ionizing radiation and mutagenic agents on plants", "Effects of radio, microwave and electronic gadget radiations and high tension electric wires on plants"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 477', 'Applications of Plant Biotechnology', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 2, 'Mass propagation of plants including endangered and underutilised species. Production of disease-free plants. Production of haploids. Somatic hybridisation. Mutation induction in vitro. Conservation and storage of plant materials in vitro. Biosynthesis of substances (secondary metabolites) in vitro. Plant genetic transformation either through somaclonal variation or direct gene transfer. Diagnostics in plant diseases. Plant biotech applications in food and agriculture, environment, medicine (medicinal plants and pharmaceuticals) and industries. GMOs and the environment. Biosafety issues/guidelines. Intellectual property rights and patents. Engineering stress, herbicide, drought, disease and pesticide tolerance, etc, in plants.', '["Mass propagation of plants, including endangered and underutilised species", "Production of disease-free plants and haploids; somatic hybridisation", "Mutation induction in vitro; conservation and storage of plant materials in vitro", "Biosynthesis of secondary metabolites in vitro", "Plant genetic transformation: somaclonal variation and direct gene transfer", "Plant biotech applications: food and agriculture, environment, medicine, industry", "GMOs and the environment; biosafety issues/guidelines; intellectual property rights and patents", "Engineering stress, herbicide, drought, disease and pesticide tolerance in plants"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 481', 'Seminar', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 2, 'PowerPoint presentation of reviews of selected and approved topics in Plant Science and Biotechnology. This gives students the opportunity to essentially read and digest many journal articles, from the internet and libraries, on a subject matter. The use of textbooks will be very minimal. Softbound copies of write-ups are expected to be submitted as a vital part of the course.', '["PowerPoint presentation of reviews of selected and approved topics", "Reading and digesting journal articles from the internet and libraries", "Submission of softbound write-ups as part of the course"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 491', 'Principles of Scientific Writing', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'first', 1, 'Definitions and history of scientific writing. The IMRAD format of scientific writing. How to write the Abstract, Introduction, Materials and Methods, Results, Discussion, Acknowledgments and cite References. How to design effective Tables and Illustrations — graphs, photographs, charts, etc.', '["Definitions and history of scientific writing", "The IMRAD format of scientific writing", "Writing the Abstract, Introduction, Materials and Methods, Results, Discussion and References", "Designing effective tables and illustrations: graphs, photographs, charts"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 422', 'Pulp and Paper Technology', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'second', 2, 'Distinction between pulp and paper. Historical perspectives on paper making. Sources of pulp materials. Pulping processes. Laboratory assessment of suitability of pulp elements for paper-making. Paper making procedure. Excursion to pulp and paper making industries in Nigeria. Fibre cell wall morphology; light microscope and ultrastructure.', '["Distinction between pulp and paper; historical perspectives on paper making", "Sources of pulp materials and pulping processes", "Laboratory assessment of suitability of pulp elements for paper-making", "Paper making procedure; excursion to pulp and paper making industries", "Fibre cell wall morphology: light microscope and ultrastructure"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 424', 'Timber Products Technology', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'second', 2, 'Distinction between wood and timber. Softwoods and hardwoods. Wood cell wall morphology under light microscope/ultrastructure. Properties of wood. Moisture characteristics of wood. Biotic agents of wood destruction. Wood preservation chemicals and treatment methods. Wood anatomy and biotechnology in criminology. Manufactured wood products. Some West African timbers and their characteristics, etc.', '["Distinction between wood and timber; softwoods and hardwoods", "Wood cell wall morphology; properties and moisture characteristics of wood", "Biotic agents of wood destruction; wood preservation chemicals and treatment methods", "Wood anatomy and biotechnology in criminology", "Manufactured wood products; West African timbers and their characteristics"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 462', 'Plant Ecology', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'second', 2, 'Population ecology, pattern, concept of plant community, vegetational changes and climax vegetation. Allelopathy, seed dispersal and dormancy. Weed ecology and control measures. Fire as an ecological factor. Primary productivity, etc.', '["Population ecology, pattern and concept of plant community", "Vegetational changes and climax vegetation", "Allelopathy, seed dispersal and dormancy", "Weed ecology and control measures", "Fire as an ecological factor; primary productivity"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 464', 'Phytoremediation and Erosion Management', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'second', 2, 'Methods of phytoremediation: phytoaccumulation and phytoextraction, rhizofiltration, phytostabilization, phytodegradation, phytovolatilization, hydraulic control of pollutants by plants, vegetation cover, etc. Plants suitable for phytoremediation. Plant enzymes involved in phytoremediation. Role of micro-organisms in degradation. Influence of environmental factors on phytoremediation. Techniques used to enhance phytoremediation. Types, causes and control of soil erosion (in Nigeria). Features of plants for erosion remediation.', '["Methods of phytoremediation: phytoaccumulation, phytoextraction, rhizofiltration, phytostabilization, phytodegradation, phytovolatilization", "Plants suitable for phytoremediation; plant enzymes involved in phytoremediation", "Role of micro-organisms in degradation; environmental factors affecting phytoremediation", "Techniques used to enhance phytoremediation", "Types, causes and control of soil erosion in Nigeria; features of plants for erosion remediation"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 466', 'Phytoindustrial Relations', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'second', 1, 'Relating plant and biotech researches to industrial needs. Initiating research efforts based on specified industrial needs. Fostering synergy between researchers and industrial concerns. Industries related to plants: mushroom, herbal soap production, herbal cosmetics, herbal teas, seed companies, plant propagation, paper and paper recycling industries, etc. Consultancy services in ecological management, conservation, wood and wood products preservation, use of phytoplankton for fish and other animal protein production, etc.', '["Relating plant and biotech research to industrial needs", "Fostering synergy between researchers and industrial concerns", "Industries related to plants: mushroom, herbal soap, herbal cosmetics, seed companies, paper recycling", "Consultancy services in ecological management and wood product preservation"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 474', 'Phytobiotechnology Ethics', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'second', 1, 'Concerns about genetically modified crops: environmental, social and economic impacts. Risk/safety assessment of GM crops. Criteria for field testing of GM crops. Risk management. National/institutional bio-safety guidelines. UNIDO/UNEP/WHO/FAO working group guidelines on bio-safety. Intellectual property rights on life forms: opportunities and concerns. Who owns biodiversity? Ethical issues involved in biotechnological processes.', '["Environmental, social and economic impacts of genetically modified crops", "Risk/safety assessment and field testing criteria for GM crops", "National/institutional bio-safety guidelines; UNIDO/UNEP/WHO/FAO guidelines on bio-safety", "Intellectual property rights on life forms; ownership of biodiversity", "Ethical issues involved in biotechnological processes"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PSB 492', 'Project', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '400 Level', 'second', 6, 'This is designed to give the student an opportunity to carry out a small independent research project on diverse aspects of Plant Science and Biotechnology, which must be approved by the Departmental Board and executed under the supervision of one or more members of staff. Two or more students may work on different aspects of a topic or subject matter. All students are expected to submit both hard and soft copies (CD) of their projects after examination and corrections.', '["Independent research project on diverse aspects of Plant Science and Biotechnology", "Project approved by the Departmental Board and executed under staff supervision", "Submission of hard and soft copies of the project after examination and corrections"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('CHM 101', 'Basic Principles of Chemistry', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '100 Level', 'first', 2, 'Stoichiometry and atomic structure: stoichiometry and mole concept. Introduction to atomic structure, development of electronic configuration of the elements, and valency theories. Periodic table and groups: the periodic classification of elements. Brief group study of representative elements, with emphasis on similarities and differences based on periodic position. Nuclear chemistry: radioactivity and its practical applications.', '["Stoichiometry and mole concept; introduction to atomic structure and valency theories", "Periodic classification of elements; brief group study of representative elements", "Nuclear chemistry: radioactivity and its practical applications"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('CHM 171', 'Basic Practical Chemistry', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '100 Level', 'first', 2, 'Laboratory operations: theory and practice of simple volumetric and quantitative analysis, simple organic preparations, functional group reactions, and physical chemistry determinations.', '["Laboratory operations: theory and practice of simple volumetric and quantitative analysis, simple organic preparations, functional group reactions, and physical chemistry determinations"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('COS 101', 'Introduction to Computer Science', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '100 Level', 'first', 2, '', '[]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('GSP 101', 'Use of English I', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '100 Level', 'first', 2, '', '[]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('GSP 103', 'Social Sciences I', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '100 Level', 'first', 2, '', '[]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('MTH 111', 'General Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '100 Level', 'first', 3, 'Elementary set theory, subsets, union, intersection, complements. Venn diagrams, real numbers, integers, rational and irrational numbers, mathematical induction, real sequences and series, theory of quadratic equations, binomial theorem. Circular measure, trigonometric functions of angles of any magnitude, addition and factor formulae. Complex numbers, algebra of complex numbers, the Argand diagram, De Moivre''s theorem, nth roots of unity.', '["Elementary set theory, subsets, union, intersection, complements", "Venn diagrams, real numbers, integers, rational and irrational numbers, mathematical induction, real sequences and series, theory of quadratic equations, binomial theorem", "Circular measure, trigonometric functions of angles of any magnitude, addition and factor formulae", "Complex numbers, algebra of complex numbers, the Argand diagram, De Moivre''s theorem, nth roots of unity"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PHY 111', 'General Physics for Life Sciences I', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '100 Level', 'first', 2, 'Units and dimension. Scalars and vectors. Linear and circular motion, velocity, acceleration. Laws of mechanics and gravitation; simple applications. Conservation of energy, momentum. Work and power. Simple harmonic motion, simple pendulum. Moment of inertia, angular momentum; centrifugal and centripetal forces; centrifuges. Elasticity, Hooke''s Law, Young''s modulus. Fluids, pressure, surface tension, velocity, osmosis; blood pressure and its measurement.', '["Units and dimension; scalars and vectors", "Linear and circular motion, velocity, acceleration", "Laws of mechanics and gravitation; conservation of energy and momentum", "Work and power; simple harmonic motion, simple pendulum", "Moment of inertia, angular momentum; centrifugal and centripetal forces; centrifuges", "Elasticity, Hooke''s Law, Young''s modulus", "Fluids: pressure, surface tension, velocity, osmosis; blood pressure and its measurement"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PHY 191', 'Practical Physics', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '100 Level', 'first', 2, 'Selected experiments from the 100-Level courses in Physics for service courses.', '["Selected experiments from the 100-Level courses in Physics for service courses"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('BIO 152', 'General Biology II', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '100 Level', 'second', 3, '', '[]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('BIO 154', 'General Biology Practical', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '100 Level', 'second', 2, '', '[]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('CHM 112', 'Basic Principles of Chemistry II', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '100 Level', 'second', 2, 'Gas laws and kinetic theory: kinetic theory of gases, elementary derivation and deduction of gas laws, molecular speeds, deviations from ideal behaviour, van der Waals modification, and gas liquefaction. Phase equilibrium and solutions: phase transitions and phase equilibria in one-component systems; ideal solutions, Raoult''s law, Henry''s law, real solutions, and colligative properties. Thermodynamics and kinetics: aspects of the first law of thermodynamics, thermochemistry, entropy, free energy, and spontaneous changes; ionic equilibria, acids, bases, indicators, and buffers; elementary chemical kinetics.', '["Gas laws and kinetic theory of gases; molecular speeds; deviations from ideal behaviour; gas liquefaction", "Phase transitions and phase equilibria; ideal and real solutions; colligative properties", "First law of thermodynamics, thermochemistry, entropy, free energy, spontaneous changes", "Ionic equilibria, acids, bases, indicators and buffers", "Elementary chemical kinetics: rate laws, order and molecularity, Arrhenius equation"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('CHM 122', 'Basic Principles of Chemistry III', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '100 Level', 'second', 2, 'Structure and classification: historical survey of organic chemistry, IUPAC nomenclature, classification of organic compounds, homologous series, elemental analysis, molecular formulas, and structural isomerism. Bonding and reactivity: isolation and purification methods, functional group concepts, resonance, and aromaticity. Functional groups: saturated and unsaturated hydrocarbons, cyclic hydrocarbons, alcohols, alkyl halides, ethers, aldehydes, ketones, carboxylic acids, amines, and aromatic compounds. Stereochemistry and lipids: introduction to oils, fats, and stereoisomerism.', '["Historical survey of organic chemistry, IUPAC nomenclature, classification of organic compounds, structural isomerism", "Isolation and purification methods; functional group concepts; resonance and aromaticity", "Saturated and unsaturated hydrocarbons, alcohols, alkyl halides, ethers, aldehydes, ketones, carboxylic acids, amines, aromatic compounds", "Introduction to oils, fats, and stereoisomerism"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('GSP 102', 'Use of English II', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '100 Level', 'second', 2, '', '[]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('GSP 104', 'Social Sciences II', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '100 Level', 'second', 2, '', '[]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PHY 112', 'General Physics for Life Sciences II', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '100 Level', 'second', 2, 'Concepts of heat, temperature: measurement of temperature, clinical thermometer. Heat capacity, specific heat, latent heat, calorimetry. Gas laws; kinetic theory of gases. Thermal energy, isothermal and adiabatic changes. Conduction, convection; radiation. Sound waves; intensity, pitch and quality of sound. Propagation of sound in solids, liquids and gases. Doppler effect. The ear. Reflection and refraction of light; plane and spherical mirrors, thin lenses; optical instruments. The eye, defects of vision and their corrections. Wave nature of light, interference, diffraction: velocity of light.', '["Concepts of heat and temperature: measurement, clinical thermometer, heat capacity, calorimetry", "Gas laws; kinetic theory of gases; thermal energy, isothermal and adiabatic changes", "Conduction, convection and radiation", "Sound waves: intensity, pitch, quality; propagation in solids, liquids and gases; Doppler effect; the ear", "Reflection and refraction of light: mirrors, thin lenses, optical instruments", "The eye, defects of vision and their corrections", "Wave nature of light: interference, diffraction, velocity of light"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('PHY 114', 'General Physics for Life Sciences III', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '100 Level', 'second', 2, 'Electric charge, Coulomb''s Law, electric field, electrostatic potential. Energy in electric field, capacitors. Dielectrics. Electric current, potential difference and electromotive force. Ohm''s Law: potentiometer, metre bridge, Wheatstone bridge. Magnetic effects of currents; permanent magnetism, earth''s magnetic field. Faraday''s Law of induction, generators and electric motor. Alternating currents; Maxwell''s equations. Structure of the atom. Radioactivity, X-rays, applications in life sciences. Nuclear energy.', '["Electric charge, Coulomb''s Law, electric field, electrostatic potential", "Energy in electric field, capacitors; dielectrics", "Electric current, potential difference and electromotive force; Ohm''s Law", "Magnetic effects of currents; permanent magnetism, earth''s magnetic field", "Faraday''s Law of induction, generators and electric motor; alternating currents; Maxwell''s equations", "Structure of the atom; radioactivity, X-rays, applications in life sciences; nuclear energy"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('MCB 102', 'Introductory Microbiology', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '100 Level', 'second', 2, 'Elective. History of development of Microbiology. Scope of Microbiology. Growth and nutrition of microorganisms. Laboratory cultivation of microorganisms and measurement of growth. Microbial metabolism and biochemistry. Control of growth of microorganisms. General characteristics, classification and economic importance of bacteriophages, fungi, algae and protozoa. Role of microorganisms in medicine, agriculture and industry.', '["History of development and scope of Microbiology", "Growth and nutrition of microorganisms", "Laboratory cultivation of microorganisms and measurement of growth", "Microbial metabolism and biochemistry", "Control of growth of microorganisms", "General characteristics, classification and economic importance of bacteriophages, fungi, algae and protozoa", "Role of microorganisms in medicine, agriculture and industry"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('BCH 201', 'General Biochemistry I', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '200 Level', 'first', 3, 'The cell environment: water and solutes — the unique properties of water, H-bonds, electrostatic interactions, Van der Waals attraction; alkalinity and acidity, pH and pK and their influence on cellular activities; physiological buffers. Cell macromolecules: structure, properties and functions of carbohydrates, lipids, proteins and nucleic acids. Cell structure and function: structure and function of major cell organelles; differences between prokaryotic and eukaryotic cells; biological membranes — organisation, architecture, properties and functions; the cytoplasm — mitochondria, peroxisomes, endoplasmic reticulum, Golgi complex, ribosomes, lysosomes, endosome; the nucleus — the nuclear envelope, chromatin, chromosomes, nucleolus, etc.', '["The cell environment: water and solutes, H-bonds, electrostatic interactions, Van der Waals attraction", "Alkalinity and acidity, pH and pK and their influence on cellular activities", "Physiological buffers", "Structure, properties and functions of carbohydrates, lipids, proteins and nucleic acids", "Structure and function of major cell organelles; differences between prokaryotic and eukaryotic cells", "Biological membranes: organisation, architecture, properties and functions", "The cytoplasm: mitochondria, peroxisomes, endoplasmic reticulum, Golgi complex, ribosomes, lysosomes, endosome", "The nucleus: nuclear envelope, chromatin, chromosomes, nucleolus"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('BIO 351', 'General Genetics', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '200 Level', 'first', 2, '', '[]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('CED 341', 'Introduction to Entrepreneurship', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '200 Level', 'first', 2, '', '[]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('GSP 207', 'Humanities I', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '200 Level', 'first', 2, '', '[]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('STA 203', 'Statistics for Agric and Biol. Sciences I', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '200 Level', 'first', 2, '', '[]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('ZEB 201', 'General Invertebrate Zoology I', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '200 Level', 'first', 2, '', '[]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('BCH 202', 'General Biochemistry II', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '200 Level', 'second', 3, 'Enzymes: introduction to biological catalysts, nature, functions and classification of enzymes, factors affecting enzyme action. Energy metabolism: introductory bioenergetics/energy-rich compounds, carbohydrate metabolism — glycolysis and pentose phosphate pathway, the Krebs cycle and the glyoxylate cycle, electron transport and oxidative phosphorylation. Separation of macromolecules: chromatographic methods — thin layer chromatography, gel filtration, ion exchange chromatography, affinity chromatography; electrophoretic methods — nucleic acid gel electrophoresis, electrophoretic sizing of protein, isoelectric focusing.', '["Introduction to biological catalysts: nature, functions and classification of enzymes; factors affecting enzyme action", "Introductory bioenergetics/energy-rich compounds", "Carbohydrate metabolism: glycolysis and pentose phosphate pathway", "The Krebs cycle and the glyoxylate cycle", "Electron transport and oxidative phosphorylation", "Chromatographic methods: thin layer, gel filtration, ion exchange, affinity chromatography", "Electrophoretic methods: nucleic acid gel electrophoresis, protein sizing, isoelectric focusing"]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
  ('BIO 352', 'Cytogenetics', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '200 Level', 'second', 2, '', '[]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
