  ('ZEB 202', 'General Invertebrate Zoology II', 'University of Nigeria, Nsukka', 'Faculty of Biological Sciences', 'Plant Science and Biotechnology', '200 Level', 'second', 2, '', '[]'::jsonb, 'Faculty of Biological Sciences course catalogue'),
